// verilir. Buradaki maliyet yalnız SIRALAMA içindir ve dışa açılmaz.
func (q *Queries) ListRentalDurationsForCatalog(ctx context.Context, arg ListRentalDurationsForCatalogParams) ([]ListRentalDurationsForCatalogRow, error) {
	rows, err := q.db.Query(ctx, listRentalDurationsForCatalog, arg.ServiceCode, arg.CountryIso)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListRentalDurationsForCatalogRow{}
	for rows.Next() {
		var i ListRentalDurationsForCatalogRow
		if err := rows.Scan(&i.DurationMinutes, &i.MinCostMicro, &i.TotalStock); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listRentalServicesWithStock = `-- name: ListRentalServicesWithStock :many
SELECT
    s.code AS service_code, s.name AS service_name, s.name_tr AS service_name_tr,
    s.icon_url,
    count(DISTINCT c.id)::bigint AS country_count,
    count(DISTINCT p.duration_minutes)::bigint AS duration_count
FROM products p
JOIN services  s ON s.id = p.service_id
JOIN countries c ON c.id = p.country_id
JOIN provider_offers o ON o.product_id = p.id AND o.is_available AND o.stock > 0
JOIN providers pr ON pr.id = o.provider_id AND pr.is_active
WHERE p.kind = 'SMS_RENTAL' AND p.is_active
  AND s.is_visible AND c.is_visible
GROUP BY s.code, s.name, s.name_tr, s.icon_url
ORDER BY s.name
`

type ListRentalServicesWithStockRow struct {
	ServiceCode   string
	ServiceName   string
	ServiceNameTr string
	IconUrl       string
	CountryCount  int64
	DurationCount int64
}

// Kiralık ızgarası: en az bir ülke×sürede stoklu servisler.
func (q *Queries) ListRentalServicesWithStock(ctx context.Context) ([]ListRentalServicesWithStockRow, error) {
	rows, err := q.db.Query(ctx, listRentalServicesWithStock)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListRentalServicesWithStockRow{}
	for rows.Next() {
		var i ListRentalServicesWithStockRow
		if err := rows.Scan(
			&i.ServiceCode,
			&i.ServiceName,
			&i.ServiceNameTr,
			&i.IconUrl,
			&i.CountryCount,
			&i.DurationCount,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listServicesWithStock = `-- name: ListServicesWithStock :many
SELECT
    s.code          AS service_code,
    s.name          AS service_name,
    s.name_tr       AS service_name_tr,
    s.icon_url,
    count(DISTINCT c.id)::bigint AS country_count,
    min(o.cost_micro)::bigint    AS min_cost_micro
FROM products p
JOIN services  s ON s.id = p.service_id
JOIN countries c ON c.id = p.country_id
JOIN provider_offers o ON o.product_id = p.id AND o.is_available AND o.stock > 0
JOIN providers pr ON pr.id = o.provider_id AND pr.is_active
WHERE p.is_active AND p.kind = 'SMS_ACTIVATION'
  AND p.verification_type = 'sms'
  AND s.is_visible AND c.is_visible
GROUP BY s.code, s.name, s.name_tr, s.icon_url
ORDER BY s.name
`

type ListServicesWithStockRow struct {
	ServiceCode   string
	ServiceName   string
	ServiceNameTr string
	IconUrl       string
	CountryCount  int64
	MinCostMicro  int64
}

// Servis IZGARASI için özet: yalnız en az bir ülkede STOKLU olan servisler,
// her biri için stoklu ülke sayısı.
//
// NEDEN AYRI BİR SORGU: gerçek katalogda 9768 stoklu servis×ülke kombinasyonu
// var ve hepsini tek yanıtta göndermek 1,09 MB ediyordu. Mobilde 4G'de bu
// kabul edilemez (docs/frontend-contract.md §8). Izgara yalnız servisleri
// gösterir; ülkeler servis seçilince ayrıca çekilir (~6 KB).
func (q *Queries) ListServicesWithStock(ctx context.Context) ([]ListServicesWithStockRow, error) {
	rows, err := q.db.Query(ctx, listServicesWithStock)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListServicesWithStockRow{}
	for rows.Next() {
		var i ListServicesWithStockRow
		if err := rows.Scan(
			&i.ServiceCode,
			&i.ServiceName,
			&i.ServiceNameTr,
			&i.IconUrl,
			&i.CountryCount,
			&i.MinCostMicro,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

