const markStaleOffersUnavailable = `-- name: MarkStaleOffersUnavailable :execrows
UPDATE provider_offers SET is_available = false, stock = 0
WHERE provider_id = $1 AND synced_at < $2 AND is_available
`

type MarkStaleOffersUnavailableParams struct {
	ProviderID int64
	SyncedAt   time.Time
}

// Senkron turunda görülmeyen teklifler "yok" sayılır. Aksi halde sağlayıcının
// listeden çıkardığı bir kombinasyon sonsuza kadar stokta görünürdü.
func (q *Queries) MarkStaleOffersUnavailable(ctx context.Context, arg MarkStaleOffersUnavailableParams) (int64, error) {
	result, err := q.db.Exec(ctx, markStaleOffersUnavailable, arg.ProviderID, arg.SyncedAt)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const resolveCountryRef = `-- name: ResolveCountryRef :one
SELECT iso2, name_tr, phone_code FROM country_reference WHERE name_key = lower($1)
`

