const upsertCountry = `-- name: UpsertCountry :one
INSERT INTO countries (iso2, name, name_tr, phone_code, supports_rent)
VALUES ($1, $2, $3, $4, $5)
ON CONFLICT (iso2) DO UPDATE
    SET name = EXCLUDED.name,
        phone_code = EXCLUDED.phone_code,
        supports_rent = EXCLUDED.supports_rent,
        name_tr = CASE WHEN countries.name_tr = '' THEN EXCLUDED.name_tr ELSE countries.name_tr END
RETURNING id, iso2, name, name_tr, phone_code, is_visible, supports_rent, created_at, updated_at
`

type UpsertCountryParams struct {
	Iso2         string
	Name         string
	NameTr       string
	PhoneCode    string
	SupportsRent bool
}

func (q *Queries) UpsertCountry(ctx context.Context, arg UpsertCountryParams) (Country, error) {
	row := q.db.QueryRow(ctx, upsertCountry,
		arg.Iso2,
		arg.Name,
		arg.NameTr,
		arg.PhoneCode,
		arg.SupportsRent,
	)
	var i Country
	err := row.Scan(
		&i.ID,
		&i.Iso2,
		&i.Name,
		&i.NameTr,
		&i.PhoneCode,
		&i.IsVisible,
		&i.SupportsRent,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

